head.script:
scwin.onpageload = function() {
    mdi01.createWindow(options);
    var options = {
        title: "frameModal Test",
        src: "./wframeModal_modaless_WESD-496_(WSQ-4614)_sub.xml",
        windowTitle: "frameModal Test",
        windowId: "M003",
        openAction: "existWindow",
        frameMode: "wframe",
        dataObject: {
            "type": "json",
            "name": "menuParam",
            "data": {
                "menuId": "M003"
            }
        }
    }
    mdi01.createWindow(options);
};
scwin.onpageunload = function() {};
scwin.onloadcompleted = function() {};


	scwin.checkVal1 = function() {
		return WebSquare.wUnit.getDomById('mdi01_subWindow0_wframe_wframePop') != null;
	}
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('mdi01_subWindow0_wframe_btn_wframeModless').click()");
		WebSquare.wUnit.addCommand("pause", "400");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('mdi01_subWindow0_wframe_wframePop').close()");
		WebSquare.wUnit.addCommand("pause", "400");		
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('mdi01_subWindow0_wframe_btn_wframePopup').click()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}	
	scwin.unitTest()
